#!/usr/bin/env node
// Hexcraft renderer for Node.js — draws a Hexcraft project (.hexmap.json) exactly as the editor
// exports it, without a browser. Generated by source/build.py from icons.js, core.js, comp.js and
// gamedata.js; do not edit by hand. Needs Node 16+ and nothing else.
//
//   const hc = require('./hexcraft-render.cjs');
//   hc.render(project, { art: true })   -> SVG string ("art only": no grid, cities, text…)
//   hc.render(project)                  -> SVG string of the full map, as File › Export › SVG
//   hc.gameData(project)                -> the .game.json object, as File › Export game data
//   hc.pageBounds(project)              -> { x, y, w, h } page area (the SVG viewBox)
//
//   node hexcraft-render.cjs map.hexmap.json [--art] [--track] [--links] [--no-sides]
//        [--transparent] [--scale 2] [--game-data] [-o out.svg]
//
// project: a parsed object or the JSON text. Text widths are estimated (no font metrics), so
// tables and long labels can differ slightly from the editor; art-only output has no text.
